            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x0A71101E094DD3B5ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD7EAA4B3120CC9A5ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x4A4652AE40E3E08BULL;
