            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = ((aWandererB + RotL64(aIngress, 13U)) + RotL64(aCarry, 5U)) + 0xFB03725606256A8DULL;
            aOrbiterI = ((aWandererG + RotL64(aScatter, 5U)) + 0x8C90ECBD6AE90653ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aCross, 35U)) + RotL64(aCarry, 57U)) + 0x69550D6D10B940AFULL;
            aOrbiterF = (((aWandererC + RotL64(aPrevious, 27U)) + RotL64(aCarry, 41U)) + 0x1690E1B64DED163AULL) + aTwistOrbiterAssignSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterB = (aWandererI + RotL64(aScatter, 19U)) + 0x27A27195B7A1C324ULL;
            aOrbiterA = (aWandererD + RotL64(aIngress, 41U)) + 0x23E123914779B439ULL;
            aOrbiterD = (aWandererK + RotL64(aPrevious, 58U)) + 0x24261072F4622636ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x247E938A42AAC2BBULL) + aTwistOrbiterUpdateSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x3965F9979B6812B2ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xCB5C315B6C619167ULL), 19U);
