            aOrbiterF = (aOrbiterF + aOrbiterH) + 0xBC39BF64BD4546A7ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x20501F135483AF44ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x05D61315E9CEAB89ULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xB7D208EDF72DF1B2ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x5D88D23B2990A086ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3E76C46A268A312FULL), 5U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xAB6EB74414659497ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0xD59E237878B8FE0DULL;
            aOrbiterH = RotL64((aOrbiterH * 0xEA03F5C1E09C0935ULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x58A5C773B1E7E12CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x1E35FCD33182CFEAULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1CE66E22AE105F93ULL), 53U);
