            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x1CCCF44470AB0B02ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x33862578DF3035C2ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x3AF7DB29A2F9EC21ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0xE2928E9041F95BB8ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xED09AE0EF5A5DBD7ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 19U)) & S_SALT1];
