            aOrbiterC = ((aWandererH + RotL64(aCross, 35U)) + 0xAC1010DAE23EC39DULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterG = ((aWandererD + RotL64(aIngress, 13U)) + RotL64(aCarry, 53U)) + 0xAE32BF609435EB0AULL;
            aOrbiterF = (((aWandererE + RotL64(aScatter, 4U)) + RotL64(aCarry, 47U)) + 0x6EB778462E8DBB23ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterJ = (aWandererA + RotL64(aIngress, 57U)) + 0x812A987E26C082B3ULL;
            aOrbiterA = ((aWandererC + RotL64(aPrevious, 43U)) + RotL64(aCarry, 43U)) + 0x80BB0C368F347837ULL;
