            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xA0FCA41DC94E6291ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x78DA9C121E71FB88ULL;
