        //      aMagmaLaneC (-->), aMagmaLaneA (-->), aLightningLaneB (<-?->)
        //
        // Cross:
        //      aMagmaLaneB (<--), aWoodLaneB (<--), aKeyRowReadA (<-?->)
        //
        // Destination:
        //      aMagmaLaneD
