            //
            aCross = (RotL64(aMagmaLaneB[((S_BLOCK1 - aIndex + 31417U)) & S_BLOCK1], 29U) ^ RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 28394U)) & S_BLOCK1], 18U));
            aCross ^= RotL64(aKeyRowReadA[(((2047U - aIndex) + 28468U)) & W_KEY1], 43U);
