            aOrbiterI = ((aWandererJ + RotL64(aIngress, 27U)) + RotL64(aCarry, 5U)) + 0xEF8217941CBDC70FULL;
            aOrbiterE = ((aWandererK + RotL64(aCross, 37U)) + 0xCF9DBB1E15A753E0ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterB = (aWandererA + RotL64(aScatter, 5U)) + 0xA764E27BBB41C265ULL;
            aOrbiterK = (((aWandererI + RotL64(aPrevious, 53U)) + RotL64(aCarry, 43U)) + 0x49CB98DBF0ECB5C2ULL) + aTwistOrbiterAssignSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterF = (aWandererH + RotL64(aIngress, 12U)) + 0x9E80B7B7B574E10CULL;
            aOrbiterD = (aWandererD + RotL64(aPrevious, 47U)) + 0xDECA6AB7546CA553ULL;
            aOrbiterJ = ((aWandererE + RotL64(aCross, 19U)) + RotL64(aCarry, 21U)) + 0xFC08FC606A2D86FDULL;
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x16C25A2CB2162198ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
