            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x37B2819AF0290E20ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x247B753EB589AC1AULL;
            aOrbiterI = RotL64((aOrbiterI * 0xDA9BDF7F34218E81ULL), 19U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0xD9CD32971A023589ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 19U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x99386ADE4C3F49CEULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xE5825D4A5BD491B5ULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x5F453C758A5F03BFULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x32E9FAEB41CC638EULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF190B1B6E3A5B059ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x70430B01C8E3B648ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0x9D834DA565EA2D06ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 8U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xD18D0C8DD72A136FULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x3651DAC0DDAF8785ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x122E5F8A061381A5ULL;
