            //
            aWandererI = aWandererI + ((RotL64(aScatter, 21U) + RotL64(aOrbiterJ, 60U)) + aOrbiterB);
            aWandererK = aWandererK ^ ((RotL64(aCross, 13U) + aOrbiterE) + RotL64(aOrbiterI, 23U));
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 27U) + aOrbiterF) + RotL64(aOrbiterB, 5U)) + RotL64(aCarry, 39U));
            aWandererE = aWandererE ^ (((RotL64(aIngress, 47U) + aOrbiterJ) + RotL64(aOrbiterD, 13U)) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aScatter, 6U) + RotL64(aOrbiterE, 41U)) + aOrbiterF);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 53U) + aOrbiterI) + RotL64(aOrbiterB, 53U));
            aWandererD = aWandererD + ((((RotL64(aCross, 35U) + RotL64(aOrbiterI, 47U)) + aOrbiterK) + RotL64(aCarry, 23U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererK, 35U) ^ aWandererH);
