            aWandererK = aWandererK ^ (((RotL64(aIngress, 57U) + RotL64(aOrbiterH, 27U)) + aOrbiterE) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aScatter, 27U) + aOrbiterB) + RotL64(aOrbiterI, 43U));
