            aCross = (RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 6235U)) & S_BLOCK1], 57U) ^ RotL64(aPlasmaLaneB[((S_BLOCK1 - aIndex + 4629U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aMagmaLaneB[((S_BLOCK1 - aIndex + 1721U)) & S_BLOCK1], 6U) ^ RotL64(aPoisonLaneD[((aIndex + 6610U)) & S_BLOCK1], 19U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCarry, 11U) + RotL64(aPrevious, 43U)) ^ (RotL64(aIngress, 23U) ^ RotL64(aCross, 56U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterF = (aWandererE + RotL64(aCross, 23U)) + 0xA81F8A76E82075CBULL;
            aOrbiterK = ((aWandererA + RotL64(aPrevious, 12U)) + 0x069BAD0B4AEF05CCULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterA = (aWandererB + RotL64(aIngress, 27U)) + 0x9712A1461E39F024ULL;
            aOrbiterJ = ((aWandererK + RotL64(aScatter, 35U)) + RotL64(aCarry, 53U)) + 0x03C46492EFB9CEC3ULL;
            aOrbiterC = ((aWandererI + RotL64(aCross, 57U)) + 0x2206FB3CEEF95FBFULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 39U)) + RotL64(aCarry, 13U)) + 0x628A440A22352C9AULL;
            aOrbiterG = (aWandererJ + RotL64(aScatter, 47U)) + 0x98C3285F1E88FD6AULL;
            aOrbiterB = ((aWandererD + RotL64(aIngress, 5U)) + RotL64(aCarry, 37U)) + 0xA3F2B301DF02F3A8ULL;
            aOrbiterD = (aWandererH + RotL64(aScatter, 18U)) + 0x325F822FE9FA2989ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x5BB2A8CEAC99546BULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x99D5148718CB6B9AULL;
            aOrbiterA = RotL64((aOrbiterA * 0x48D9E5ADC8D499EFULL), 23U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0x366362D433C244D0ULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0xCEA77C1C0A2C75D1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1B75342E744538F5ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xAAB293EF6C8AC2B5ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x55FA2CC2ACE0E330ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x8A7CC38896FE5457ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x7381B14D962D22A1ULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x7E9890B781531D97ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x16ECBBAB7AC369C1ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x266B75A2EBA8111EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x4F5A32D842C17AADULL;
