            aOrbiterH = RotL64((aOrbiterH * 0x44EE94E27CEFDE49ULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x18BE4E034B0B1ADAULL) + aKeySpawnOrbiterUpdateSaltB[((aIndex + 22U)) & S_SALT1];
