            aIngress ^= (RotL64(aIceLaneB[((aIndex + 8049U)) & S_BLOCK1], 5U) ^ RotL64(aHeartLaneA[((S_BLOCK1 - aIndex + 8613U)) & S_BLOCK1], 20U));
