            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 7496U)) & S_BLOCK1], 3U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 8525U)) & S_BLOCK1], 18U));
            aCross ^= (RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 9731U)) & S_BLOCK1], 35U) ^ RotL64(aKeyRowReadB[((aIndex + 6984U)) & W_KEY1], 27U));
            aCross = TwistMix64::DiffuseC(aCross);
