            aOrbiterF = (aOrbiterF + aOrbiterA) + 0xAE9C2949388C3B0CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x59AC439FD85365EFULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x3534F746325D44E7ULL), 39U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0x2D8BD169E3C8E44FULL) + aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xAA966397D91D4575ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9264F85B9AF24327ULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xEC50AA0F92FDAC30ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xD24167A8BB49B890ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7CEB1CAB2767917DULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x9C616BD34824ABF3ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x13EE4D41EEB6C68EULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD958EC78B01957BBULL), 3U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x0ED2F34A8AC1EA7DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xF80A294127914724ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x05E45570E5703223ULL), 47U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0xB185E1EBE0D97593ULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x308D41EE99EE17D1ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x2D7266C7E84EE529ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x78CB0D6A9B35A989ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x348EB985692E38A7ULL;
