            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x6332447F62EB7267ULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x410FBE5DB7BCC398ULL;
